<script lang="ts">import {untrack}from'svelte';import Button from '../../design-system/components/Button.svelte';import FormField from '../../design-system/components/FormField.svelte';import type{StoredPatient}from'../../lib/mockOperations';let{initial,onSave,onCancel}:{initial?:StoredPatient;onSave:(patient:StoredPatient)=>void;onCancel:()=>void}=$props();let values=$state(untrack(()=>({name:initial?.name??'',cpf:initial?.cpf??'',birth:initial?.birth??'',phone:initial?.phone??'',status:initial?.status??'Ativo'})));let error=$state('');function submit(e:SubmitEvent){e.preventDefault();if(!values.name||values.cpf.replace(/\D/g,'').length!==11||!values.birth||!values.phone){error='Preencha corretamente os dados obrigatórios.';return}onSave({id:initial?.id??`pat-${Date.now()}`,...values,lastVaccine:initial?.lastVaccine??'Nenhuma aplicação registrada'})}</script>
<div class="backdrop" role="presentation" onclick={(e)=>e.target===e.currentTarget&&onCancel()}><div role="dialog" aria-modal="true" aria-labelledby="patient-title"><form onsubmit={submit}><header><div><p>Cadastro clínico</p><h2 id="patient-title">{initial?'Editar paciente':'Novo paciente'}</h2></div><button type="button" aria-label="Fechar" onclick={onCancel}>×</button></header>{#if error}<div class="error" role="alert">{error}</div>{/if}<div class="grid"><FormField id="patient-name" label="Nome completo" value={values.name} oninput={(v)=>values.name=v} required/><FormField id="patient-cpf" label="CPF" value={values.cpf} oninput={(v)=>values.cpf=v} required/><FormField id="patient-birth" label="Data de nascimento" value={values.birth} placeholder="DD/MM/AAAA" oninput={(v)=>values.birth=v} required/><FormField id="patient-phone" label="Telefone" type="tel" value={values.phone} oninput={(v)=>values.phone=v} required/><label>Situação<select bind:value={values.status}><option>Ativo</option><option>Inativo</option></select></label></div><footer><Button variant="secondary" onclick={onCancel}>Cancelar</Button><Button type="submit">Salvar paciente</Button></footer></form></div></div>
<style>.backdrop{position:fixed;z-index:90;inset:0;display:grid;place-items:center;background:var(--surface-overlay);padding:var(--space-5)}form{width:min(100%,38rem);border:1px solid var(--border-subtle);border-radius:var(--radius-lg);background:var(--surface-card);padding:var(--space-6);box-shadow:var(--shadow-md)}header{display:flex;justify-content:space-between;margin-bottom:var(--space-5)}header p{color:var(--color-brand-500);font-size:var(--text-xs);font-weight:800;text-transform:uppercase}h2{margin-top:.2rem;font-size:var(--text-xl)}header button{border:0;background:transparent;color:var(--text-secondary);font-size:1.5rem;cursor:pointer}.grid{display:grid;grid-template-columns:1fr 1fr;gap:var(--space-4)}label{display:grid;gap:var(--space-2);font-size:var(--text-sm);font-weight:650}select{min-height:2.875rem;border:1px solid var(--border-strong);border-radius:var(--radius-md);background:var(--surface-card);padding:0 var(--space-3);color:var(--text-primary)}.error{margin-bottom:var(--space-4);border-radius:var(--radius-sm);background:var(--status-danger-bg);padding:var(--space-3);color:var(--status-danger);font-size:var(--text-sm)}footer{display:flex;justify-content:flex-end;gap:var(--space-3);margin-top:var(--space-6);border-top:1px solid var(--border-subtle);padding-top:var(--space-5)}@media(max-width:600px){.grid{grid-template-columns:1fr}}</style>
